<?php
namespace App\Livewire\Members;
use App\Models\Student;
use App\Models\LibraryClass;
use Livewire\Component;
use Livewire\WithPagination;
class StudentIndex extends Component { use WithPagination; public string $search=''; public string $studentNumber=''; public string $fullName=''; public ?int $classId=null; public string $status='active'; public bool $isActive=true; public ?int $editingId=null; public function updatedSearch(){ $this->resetPage(); } public function edit(int $id){$x=Student::findOrFail($id);$this->editingId=$id;$this->studentNumber=$x->student_number;$this->fullName=$x->full_name;$this->classId=$x->class_id;$this->status=$x->status;$this->isActive=$x->is_active;} public function resetForm(){ $this->reset(['editingId','studentNumber','fullName','classId']);$this->status='active';$this->isActive=true;} public function save(){ $d=$this->validate(['studentNumber'=>['required','string','max:100','unique:students,student_number,'.$this->editingId],'fullName'=>'required|string|max:255','classId'=>'nullable|exists:classes,id','status'=>'required|in:active,inactive,graduated','isActive'=>'boolean']); Student::updateOrCreate(['id'=>$this->editingId],['student_number'=>$d['studentNumber'],'full_name'=>$d['fullName'],'class_id'=>$d['classId'],'status'=>$d['status'],'is_active'=>$d['isActive']]);$this->resetForm();session()->flash('success','Data siswa berhasil disimpan.');} public function deactivate(int $id): void { Student::findOrFail($id)->update(['is_active'=>false]); session()->flash('success','Siswa dinonaktifkan.'); } public function render(){return view('livewire.members.student-index',['classes'=>LibraryClass::orderBy('name')->get(),'students'=>Student::with('classRoom')->where('is_active',true)->when($this->search,fn($q)=>$q->where('student_number','like','%'.$this->search.'%')->orWhere('full_name','like','%'.$this->search.'%'))->latest()->paginate(10)])->layout('components.layouts.app',['heading'=>'Data Siswa']);}}
